class Solution:
    def countSeniors(self, details: list[str]) -> int:
        return sum(1 for s in details if int(s[11:13]) > 60)

class Solution {
public:
    int countSeniors(std::vector<std::string>& details) {
        int count = 0;
        for (const auto& s : details) {
            int age = (s[11] - '0') * 10 + (s[12] - '0');
            if (age > 60) count++;
        }
        return count;
    }
};

class Solution {
    public int countSeniors(String[] details) {
        int count = 0;
        for (String s : details) {
            int age = (s.charAt(11) - '0') * 10 + (s.charAt(12) - '0');
            if (age > 60) count++;
        }
        return count;
    }
}

var countSeniors = function(details) {
    let count = 0;
    for (const s of details) {
        const age = parseInt(s.slice(11, 13), 10);
        if (age > 60) count++;
    }
    return count;
};
